# genex.toml
[render]
form_factors = ["desktop", "mobile"]
preset = "auto"

[render.look]
tonemapper = "agx-punchy"  # khronos-neutral keeps authored colours; plain agx greys saturated lights
exposure = "auto"
ev_compensation = 0.5        # a sunlit scene, under any curve

[render.class.mobile-mid]
render_scale = 0.67
bloom = false

// src/game.rs
game.on_ui(|sim, ui, _| {
    if sim.world.options_open {
        genex::render::settings_panel(ui); // the person's choice, saved per device, never in the Sim
    }
});
